function norm(s){return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();}
function toks(s){return norm(s).split(' ').filter(Boolean);}
var STOP=new Set(['dr','drs','doctor','docteur','dokte','doktor','dokt','doc','md','mr','mrs','ms','mme','m']);
